# timer: a Mealy machine, generated by Silinx from the ASM chart timer.asm.json (edit the drawing, not this file).
# MicroPython for the ESP32 DevKit. One tick every TICK_MS milliseconds: the inputs read once at its start, the outputs
# written to their pins at its end (Silinx's synchronous reactive model: docs/SYSTEMS.md).
# Inputs: start GPIO4, tick GPIO13, secs GPIO14 GPIO16 GPIO17 GPIO18.
# Outputs: done GPIO19, left GPIO21 GPIO22 GPIO23 GPIO25.
# (a port of several bits: its pins bit 0 first)

from machine import Pin
import time

# ---- the pins
PIN_START = Pin(4, Pin.IN)
PIN_TICK = Pin(13, Pin.IN)
PIN_SECS = (Pin(14, Pin.IN), Pin(16, Pin.IN), Pin(17, Pin.IN), Pin(18, Pin.IN))
PIN_DONE = Pin(19, Pin.OUT)
PIN_LEFT = (Pin(21, Pin.OUT), Pin(22, Pin.OUT), Pin(23, Pin.OUT), Pin(25, Pin.OUT))

TICK_MS = 10  # the tick's period

# ---- the states
S_IDLE = 0
S_COUNT = 1

# ---- the inputs, read once per tick
start = 0
tick = 0
secs = 0  # 4 bits

# ---- the outputs
done = 0
left = 0  # 4 bits

# ---- the memory
state = S_IDLE
cnt = 0  # 4 bits


# a number from its pins, bit 0 first
def read_bits(pins):
    v = 0
    for i in range(len(pins)):
        if pins[i].value():
            v |= 1 << i
    return v


# a number to its pins, bit 0 first
def write_bits(pins, v):
    for i in range(len(pins)):
        pins[i].value((v >> i) & 1)


def read_inputs():
    global start, tick, secs
    start = PIN_START.value()
    tick = PIN_TICK.value()
    secs = read_bits(PIN_SECS)


def write_outputs():
    PIN_DONE.value(done)
    write_bits(PIN_LEFT, left)


# the reset state
def reset_machine():
    global state, cnt
    state = S_IDLE
    cnt = 0


# one tick: the outputs of the present state and of the inputs, then the next state
def step_machine():
    global state, cnt, done, left
    read_inputs()
    # the outputs' defaults
    done = 0
    left = 0
    if state == S_IDLE:
        if start:
            cnt = 0
            state = S_COUNT
    elif state == S_COUNT:
        left = (secs - cnt) & 0xF
        if tick:
            if cnt == (secs - 1) & 0xFFFFFFFF:
                done = 1
                state = S_IDLE
            else:
                cnt = (cnt + 1) & 0xF
    write_outputs()


# the reset state, then a tick every TICK_MS milliseconds
def main():
    reset_machine()
    last = time.ticks_ms()
    while True:
        if time.ticks_diff(time.ticks_ms(), last) >= TICK_MS:
            last = time.ticks_add(last, TICK_MS)
            step_machine()


main()
